H,W=23,28
zeros={1:[4,13,19,25],2:[1,7,16,22],3:[11],4:[24],5:[2,9,14,21],7:[5,12,17],9:[9,19],10:[4,16],11:[1,13,22],12:[6],13:[3,10],14:[14,21,25],15:[7],16:[1,19],17:[10,15],18:[4,26],20:[2,17,21],21:[7,12]}
# build background + source emblem
G=[[4]*W for _ in range(H)]
for r,cs in zeros.items():
 for c in cs:G[r][c]=0
G[8][25]=6; G[9][24:27]=[3,9,5]; G[10][25]=2
# stamp + motif centered on each zero, record conflicts
out=[row[:] for row in G]
conf=[]
for r,cs in zeros.items():
 for c in cs:
  for dr,dc,val in [(-1,0,6),(0,-1,3),(0,0,9),(0,1,5),(1,0,2)]:
   rr,cc=r+dr,c+dc
   if 0<=rr<H and 0<=cc<W:
    if out[rr][cc] not in (4,0,val): conf.append((rr,cc,out[rr][cc],val,(r,c)))
    out[rr][cc]=val
print('conflicts',conf)
print('markers',sum(map(len,zeros.values())))
print('\n'.join(' '.join(map(str,row)) for row in out))
